/*
 * @lc app=leetcode id=1397 lang=kotlin
 *
 * [1397] Find All Good Strings
 */

class Solution { fun findGoodStrings(n: Int, s1: String, s2: String, evil: String): Int = IntArray(evil.length).also { lps -> (1 until evil.length).fold(0) { j, i -> generateSequence(j) { k -> if (k > 0 && evil[i] != evil[k]) lps[k - 1] else null }.first { k -> k == 0 || evil[i] == evil[k] }.let { k -> (if (evil[i] == evil[k]) k + 1 else 0).also { lps[i] = it } } } }.let { lps -> HashMap<Int, Int>().let { memo -> DeepRecursiveFunction<Int, Int> { state -> if ((state shr 2) and 63 == evil.length) 0 else if (state shr 8 == n) 1 else memo.getOrPut(state) { (state shr 8).let { pos -> ((state shr 2) and 63).let { eLen -> ((state and 2) != 0).let { b1 -> ((state and 1) != 0).let { b2 -> (if (b1) s1[pos] else 'a').let { minC -> (if (b2) s2[pos] else 'z').let { maxC -> (minC..maxC).fold(0L) { acc, c -> generateSequence(eLen) { k -> if (k > 0 && c != evil[k]) lps[k - 1] else null }.first { k -> k == 0 || c == evil[k] }.let { k -> if (c == evil[k]) k + 1 else 0 }.let { nextE -> (acc + callRecursive((pos + 1 shl 8) or (nextE shl 2) or ((if (b1 && c == s1[pos]) 1 else 0) shl 1) or (if (b2 && c == s2[pos]) 1 else 0))) % 1000000007 } }.toInt() } } } } } } } }.invoke(3) } } }